import 'dart:io';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:nothingness/models/screen_config.dart';
import 'package:nothingness/models/song_info.dart';
import 'package:nothingness/models/transport_position.dart';
import 'package:nothingness/services/library_browser.dart';
import 'package:nothingness/services/library_service.dart';
import 'package:nothingness/services/settings_service.dart';
import 'package:nothingness/services/playback_controller.dart';
import 'package:nothingness/screens/void_screen.dart';
import 'package:nothingness/widgets/heroes/_test_helpers.dart';

import '../widgets/heroes/_test_helpers.dart';
import '../widgets/mid_ellipsis.dart';

import 'package:nothingness/models/audio_track.dart';
import 'package:nothingness/widgets/hero_feedback_surface.dart';
import 'package:nothingness/theme/themes.dart';
import 'package:nothingness/models/theme_id.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:nothingness/widgets/press_feedback.dart';
import 'package:nothingness/widgets/transport_row.dart';
import 'package:path/path.dart' as p;
import 'package:nothingness/controllers/library_controller.dart';

class _RecordingLibraryController extends LibraryController {
  _RecordingLibraryController({
    String? currentPath,
    List<AudioTrack> tracks = const <AudioTrack>[],
  }) : super(
          libraryBrowser: LibraryBrowser(supportedExtensions: const {'mp3'}),
          libraryService: LibraryService(),
          isAndroidOverride: false,
        ) {
    this.currentPath = currentPath;
    this.tracks = List<AudioTrack>.from(tracks);
    hasPermission = true;
  }

  final List<String> loadFolderCalls = <String>[];

  @override
  Future<void> loadFolder(String path) async {
    loadFolderCalls.add(path);
    currentPath = path;
    notifyListeners();
  }
}

Future<void> _writeBoundaryPng(
  WidgetTester tester, {
  required GlobalKey key,
  required String outPath,
}) async {
  final boundaryFinder = find.byKey(key);
  expect(boundaryFinder, findsOneWidget);
  final boundary = tester.renderObject(boundaryFinder) as RenderRepaintBoundary;
  final image = await boundary.toImage(pixelRatio: 1.0);
  final byteData = await image.toByteData(format: ui.ImageByteFormat.png);
  expect(byteData, isNotNull);
  final bytes = byteData!.buffer.asUint8List();

  await File(outPath).writeAsBytes(bytes, flush: true);
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  setUp(() async {
    SharedPreferences.setMockInitialValues(<String, Object>{});
    SettingsService().immersiveNotifier.value = false;
    SettingsService().transportPositionNotifier.value = TransportPosition.bottom;
  });

  testWidgets('swipe-to-seek feedback: crumb shows preview while dragging and clears after',
      (tester) async {
    await tester.binding.setSurfaceSize(const Size(800, 1600));

    final boundaryKey = GlobalKey();
    final provider = FakeAudioPlayerProvider(
      songInfo: SongInfo(
        track: const AudioTrack(path: '/lib/Music/x.wav', title: 'x'),
        isPlaying: true,
        position: 10000,
        duration: 60000,
      ),
      isPlaying: true,
    );

    final lib = _RecordingLibraryController(
      currentPath: '/lib/Music',
      tracks: const <AudioTrack>[],
    );

    final app = MaterialApp(
      theme: buildAppTheme(
        id: ThemeId.void_,
        brightness: Brightness.dark,
      ),
      home: Scaffold(
        body: RepaintBoundary(
          key: boundaryKey,
          child: VoidScreen(
            config: const SpectrumScreenConfig(),
            settings: const SpectrumSettings(),
            libraryController: lib,
          ),
        ),
      ),
    );

    await tester.pumpWidget(ChangeNotifierProvider<PlaybackController>.value(
      value: provider,
      child: app,
    ));

    await tester.pump();

    final hero = find.byType(HeroFeedbackSurface);
    expect(hero, findsOneWidget);

    final shotsDir = p.join('.tmp', 'agent_shots');
    Directory(shotsDir).createSync(recursive: true);

    final duringPath = p.join(shotsDir, 'seek_preview_during.png');
    final afterPath = p.join(shotsDir, 'seek_preview_after.png');

    final gesture = await tester.startGesture(tester.getCenter(hero));
    await gesture.moveBy(const Offset(160, 0));
    await tester.pump(const Duration(milliseconds: 16));

    await _writeBoundaryPng(
      tester,
      key: boundaryKey,
      outPath: duringPath,
    );

    await gesture.up();
    await tester.pumpAndSettle();

    await _writeBoundaryPng(
      tester,
      key: boundaryKey,
      outPath: afterPath,
    );

    expect(File(duringPath).existsSync(), isTrue);
    expect(File(afterPath).existsSync(), isTrue);
  });
}

